import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Map;
import java.util.TreeMap;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Checks that every translation has exactly the keys of the English source and the same %n$s placeholders.
 * <p>
 * en_us.json is generated by {@code ./gradlew runData}; other languages are hand-written under src/main/resources.
 * Run from the project root with a plain JDK 21, no dependencies:
 * <pre>java tools/LangCheck.java</pre>
 * Exit code 1 if anything is missing, extra or has mismatched placeholders.
 */
public class LangCheck {
	static final String MOD = "create_pocketdynamo";
	static final Path SOURCE = Path.of("src/generated/resources/assets/" + MOD + "/lang/en_us.json");
	static final Path[] TRANSLATIONS = { Path.of("src/main/resources/assets/" + MOD + "/lang/es_es.json") };
	static final Pattern ENTRY = Pattern.compile("^\\s*\"((?:[^\"\\\\]|\\\\.)*)\"\\s*:\\s*\"((?:[^\"\\\\]|\\\\.)*)\"\\s*,?\\s*$");
	static final Pattern PLACEHOLDER = Pattern.compile("%\\d+\\$s");

	static Map<String, String> read(Path file) throws IOException {
		Map<String, String> entries = new TreeMap<>();
		for (String line : Files.readAllLines(file)) {
			Matcher m = ENTRY.matcher(line);
			if (m.matches())
				entries.put(m.group(1), m.group(2));
		}
		return entries;
	}

	static String placeholders(String value) {
		Matcher m = PLACEHOLDER.matcher(value);
		StringBuilder sb = new StringBuilder();
		while (m.find())
			sb.append(m.group()).append(' ');
		return sb.toString().trim();
	}

	public static void main(String[] args) throws IOException {
		Map<String, String> source = read(SOURCE);
		int problems = 0;
		for (Path file : TRANSLATIONS) {
			Map<String, String> translation = read(file);
			for (String key : source.keySet()) {
				if (!translation.containsKey(key)) {
					System.out.println(file.getFileName() + ": MISSING " + key);
					problems++;
				} else if (!placeholders(source.get(key)).equals(placeholders(translation.get(key)))) {
					System.out.println(file.getFileName() + ": PLACEHOLDER MISMATCH " + key);
					problems++;
				}
			}
			for (String key : translation.keySet()) {
				if (!source.containsKey(key)) {
					System.out.println(file.getFileName() + ": EXTRA " + key);
					problems++;
				}
			}
			System.out.println(file.getFileName() + ": " + translation.size() + " keys vs " + source.size() + " in en_us");
		}
		if (problems > 0) {
			System.out.println(problems + " problem(s)");
			System.exit(1);
		}
		System.out.println("OK");
	}
}
